import Foundation
import SwiftData

// Bump this number whenever new exercises are added — the app will reseed on next launch.
//
// Was left at 4 while the catalog below grew to 405 entries, so every device that had already
// seeded v4 kept its old, much smaller catalog: a live store held 68 distinct exercises and the
// picker simply could not find most common lifts. If you add rows below and don't touch this, the
// additions ship dead.
private let kCatalogVersion = 6

enum ExerciseCatalog {

    static func seedIfNeeded(context: ModelContext) {
        let saved = UserDefaults.standard.integer(forKey: "exerciseCatalogVersion")
        guard saved < kCatalogVersion else { return }

        // Remove all non-custom global exercises so we can replace with the full catalog.
        let descriptor = FetchDescriptor<ExerciseDefinitionRecord>(
            predicate: #Predicate { !$0.isCustom && $0.ownerID == "" }
        )
        if let stale = try? context.fetch(descriptor) {
            stale.forEach { context.delete($0) }
        }

        // Guard against the catalog listing the same lift twice: it's a 400-row hand-maintained
        // literal, and "Deficit Deadlift" was in fact duplicated, which showed up as a doubled row in
        // the picker. Dedupe here so a slip in the list below can't reach the store.
        var seen = Set<String>()
        for ex in catalog where seen.insert(MuscleTaxonomy.normalize(ex.0)).inserted {
            context.insert(ExerciseDefinitionRecord(
                name: ex.0,
                primaryMuscle: ex.1,
                secondaryMusclesJSON: encodeSecondary(ex.2),
                equipment: ex.3,
                movementPattern: ex.4
            ))
        }
        try? context.save()
        UserDefaults.standard.set(kCatalogVersion, forKey: "exerciseCatalogVersion")
    }

    private static func encodeSecondary(_ muscles: [String]) -> String {
        (try? String(data: JSONEncoder().encode(muscles), encoding: .utf8)) ?? "[]"
    }

    // Bodyweight exercises where the user can attach extra load (belt, vest, plate).
    // The weight field for these exercises represents added weight only.
